        public int InsertMessageDetails(List<MessageReceiverDetailsBL> aoMessageReceiverDetailsBLList, List<string> alstFiles)
        {
            ArrayList oArrayListInsertStatements = new ArrayList(); 
            moMessageDetailsDC.MessageDetailsStructDetails = moMessageDetailsStruct;
            oArrayListInsertStatements.Add(moMessageDetailsDC.GetInsertMessageDetails());
            oArrayListInsertStatements.Add("SELECT SCOPE_IDENTITY() as "+ Constants.S_LAST_INSERTED_P_KEY);
  
            foreach (MessageReceiverDetailsBL oMessageReceiverDetailsBL in aoMessageReceiverDetailsBLList)
                oArrayListInsertStatements.Add(oMessageReceiverDetailsBL.GetInsertMessageReceiverDetails());

            foreach (string path in alstFiles)
            {
                MessageReceiverDetailsBL oMessageReceiverDetailsBL =new MessageReceiverDetailsBL();
                oArrayListInsertStatements.Add(moMessageDetailsDC.GetInsertAttachmentDetails(path));
            }

            return moMessageDetailsDC.InsertMessageDetails(oArrayListInsertStatements);
        }
        
