    public class MessageDetailsCollectionBL
    {
        private MessageDetailsCollectionDC moMessageDetailsCollectionDC = null;

        private int miMessagesCount;

        public DataTable GetMessages(int aiAcadYrId, int aiUserId, int aiUserRoleId, string asMode, string asFilter,string asOperator, string dtDate, String sortExpression, int maximumRows, int startRowIndex)
        {
            const string S_FLAG_SHOW_INBOX = "ShowInbox";
            const string S_FLAG_SHOW_SENT_ITEMS = "ShowSentItems";
            const string S_FLAG_SHOW_TRASH = "ShowTrash";
            DateTime dt = new DateTime();      

            if (asFilter == null)
                asFilter = string.Empty;
            if (dtDate == null)
                dt = DateTime.MinValue;
            else               
                dt = DateTime.Parse(dtDate.ToString());

            DataTable oDt = new DataTable();
            miMessagesCount = 0;
            switch (asMode)
            {
                case S_FLAG_SHOW_INBOX:
                    oDt = moMessageDetailsCollectionDC.GetMessageInboxForUser(aiAcadYrId, aiUserId, aiUserRoleId, sortExpression, maximumRows, startRowIndex, asFilter, asOperator, dt);
                    break;
                case S_FLAG_SHOW_TRASH:
                     oDt = moMessageDetailsCollectionDC.GetArchivedMessagesForUser(aiAcadYrId, aiUserId, aiUserRoleId, sortExpression, maximumRows, startRowIndex, asFilter, asOperator, dt);
                     break;
                case S_FLAG_SHOW_SENT_ITEMS:
                    oDt = moMessageDetailsCollectionDC.GetSentItemsForUser(aiAcadYrId, aiUserId, aiUserRoleId, sortExpression, maximumRows, startRowIndex, asFilter, asOperator, dt);
                    break;
                default:
                    oDt = moMessageDetailsCollectionDC.GetMessageInboxForUser(aiAcadYrId, aiUserId, aiUserRoleId, sortExpression, maximumRows, startRowIndex, asFilter,asOperator,dt);
                    break;
            }

            if (oDt != null && oDt.Rows.Count > 0)
                miMessagesCount = Convert.ToInt32(oDt.Rows[0]["TotalRows"]);

            return oDt;
        }
        public int GetMsgCount(int aiAcadYrId, int aiUserId, int aiUserRoleId, string asMode, string asFilter, string asOperator,string dtDate)
        {
            return miMessagesCount;
        }

